/* GF goal-panel carousel and live viewer colours v14 */
const ghGoalModels=['o1','p1','circle-cage-1','circle-cage-2','octagon','street-field'],ghGoalCoats=['gray','red','blue','green'];let ghGoalCleanup=()=>{};
const ghGoalImage=(arena,coat)=>data.studio+'/product-goals/v14/'+arena+'-'+coat+'.png';
function ghGoalRefresh(viewer){
 const arena=viewer.dataset.arena,coat=viewer.dataset.coat,view=viewer.dataset.view;title.textContent=data.names[arena]+(view==='goal'?' — panel bramkowy':' — model 3D');
 const cta=body.querySelector('[data-preview-personalize]');if(cta)cta.href=data.studio+'/?'+new URLSearchParams({arena,coat});
 const full=body.querySelector('.gh-goal-full');if(full)full.hidden=view!=='goal';
 body.querySelectorAll('[data-goal-arena]').forEach(button=>{button.setAttribute('aria-pressed',String(view==='goal'&&button.dataset.goalArena===arena));const image=button.querySelector('img'),src=ghGoalImage(button.dataset.goalArena,coat);if(image.src!==src)image.src=src});
}
window.addEventListener('message',event=>{
 if(!dialog.open||!frame||!frame.classList.contains('gh-product-viewer-frame')||event.source!==frame.contentWindow||event.origin!==new URL(data.studio).origin)return;
 const message=event.data;if(!message||message.type!=='gf-product-viewer-coat'||!ghGoalModels.includes(message.arena)||!ghGoalCoats.includes(message.coat)||message.arena!==frame.dataset.arena||message.view!==frame.dataset.view||message.viewerId!==frame.dataset.viewerId)return;
 frame.dataset.coat=message.coat;ghGoalRefresh(frame);
});
dialog.addEventListener('close',()=>{if(!dialog.open)ghGoalCleanup()});
root.addEventListener('click',event=>{
 const button=event.target instanceof Element?event.target.closest('[data-open-3d],.gh-hero-mobile-3d'):null;if(!button||!root.contains(button))return;event.preventDefault();event.stopImmediatePropagation();ghGoalCleanup();
 const initialCoat=ghGoalCoats.includes(heroColour)?heroColour:'gray';open(data.names[model]+' — model 3D',button);
 const note=node('p',{className:'gh-load-status',role:'status'},'Wczytujemy podgląd konstrukcji…');
 const url=(arena,coat,view,viewerId)=>data.studio+'/product-viewer?'+new URLSearchParams({arena,coat,parentOrigin:location.origin,viewerId,ui:'14',...(view==='goal'?{view:'goal'}:{})});
 const initialId=crypto.randomUUID();const viewer=node('iframe',{className:'gh-frame gh-product-viewer-frame',title:'Wizualizacja konstrukcji 3D',src:url(model,initialCoat,'court',initialId)});frame=viewer;viewer.dataset.arena=model;viewer.dataset.coat=initialCoat;viewer.dataset.view='court';viewer.dataset.viewerId=initialId;viewer.addEventListener('load',()=>{if(frame!==viewer)return;note.remove();clearTimeout(timeout)});
 const gallery=node('section',{className:'gh-goal-gallery'});gallery.setAttribute('aria-label','Panele bramkowe od zewnątrz');const full=node('button',{type:'button',className:'gh-btn gh-goal-full'},'← Całe boisko');full.hidden=true;
 const header=node('div',{className:'gh-goal-header'}),head=node('div');head.append(node('h3',{},'Panele bramkowe'),node('p',{},'Na wprost, od zewnętrznej strony.'));const nav=node('div',{className:'gh-goal-nav'}),previous=node('button',{type:'button',className:'gh-btn'},'←'),next=node('button',{type:'button',className:'gh-btn'},'→');previous.setAttribute('aria-label','Poprzednie panele bramkowe');next.setAttribute('aria-label','Następne panele bramkowe');nav.append(previous,next);header.append(head,nav);
 const rail=node('div',{className:'gh-goal-rail',id:'gh-goal-panels'});rail.tabIndex=0;rail.setAttribute('aria-label','Warianty paneli bramkowych');previous.setAttribute('aria-controls',rail.id);next.setAttribute('aria-controls',rail.id);
 const goTo=(arena,view)=>{if(frame!==viewer||!dialog.open||(viewer.dataset.arena===arena&&viewer.dataset.view===view))return;viewer.dataset.arena=arena;viewer.dataset.view=view;ghGoalRefresh(viewer);viewer.dataset.viewerId=crypto.randomUUID();viewer.src=url(arena,viewer.dataset.coat,view,viewer.dataset.viewerId);viewer.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
 const abort=new AbortController(),listen={signal:abort.signal};
 for(const arena of ghGoalModels){const card=node('button',{type:'button',className:'gh-goal-card'});card.dataset.goalArena=arena;card.setAttribute('aria-label',data.names[arena]+' — cały panel bramkowy od zewnątrz');card.setAttribute('aria-pressed','false');const img=node('img',{src:ghGoalImage(arena,initialCoat),alt:data.names[arena]+' — pełny panel z bramką, widok od zewnątrz',width:720,height:320});img.loading='lazy';img.decoding='async';card.append(img,node('span',{},data.names[arena]));card.addEventListener('click',()=>goTo(arena,'goal'),listen);rail.append(card)}
 full.addEventListener('click',()=>goTo(viewer.dataset.arena,'court'),listen);
 const update=()=>{const max=rail.scrollWidth-rail.clientWidth;previous.disabled=rail.scrollLeft<=3;next.disabled=max<=3||rail.scrollLeft>=max-3};
 const move=direction=>{const card=rail.querySelector('button');if(card)rail.scrollBy({left:direction*(card.getBoundingClientRect().width+12),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};previous.addEventListener('click',()=>move(-1),listen);next.addEventListener('click',()=>move(1),listen);rail.addEventListener('scroll',update,{passive:true,signal:abort.signal});const observer=new ResizeObserver(update);observer.observe(rail);ghGoalCleanup=()=>{abort.abort();observer.disconnect()};gallery.append(full,header,rail);
 const invite=node('div',{className:'gh-preview-invite'}),copy=node('div');copy.append(node('h3',{},'Nadaj mu swój charakter.'),node('p',{},'Dopasuj kolory, logo i detale konstrukcji w Studio.'));const cta=link('Personalizuj w Studio',data.studio+'/?'+new URLSearchParams({arena:model,coat:initialCoat}));cta.classList.add('gh-primary');cta.dataset.previewPersonalize='';invite.append(copy,cta);body.append(note,viewer,gallery,invite);update();
 timeout=setTimeout(()=>{if(frame===viewer&&dialog.open)note.textContent='Podgląd potrzebuje więcej czasu. Możesz też przejść do personalizacji w Studio.'},20000);
},true);
const ghGoalStyle=document.createElement('style');ghGoalStyle.textContent='.gh-goal-gallery{margin-top:18px;min-width:0}.gh-goal-header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.gh-goal-header h3{font-size:20px;margin:0 0 4px}.gh-goal-header p{font-size:13px;color:var(--gh-muted);margin:0}.gh-goal-nav{display:flex;gap:5px}.gh-goal-nav>.gh-btn{width:36px;height:36px;min-width:36px;padding:0;justify-content:center;font-size:20px}.gh-goal-nav>.gh-btn:disabled{opacity:.32;cursor:default}.gh-goal-rail{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 24px)/3);gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;padding:3px 2px 10px;scrollbar-width:thin}.gh-goal-card{display:flex;flex-direction:column;align-items:stretch;gap:4px;min-width:0;padding:8px;border:1px solid var(--gh-line);border-radius:12px;background:#fff;color:var(--gh-ink);cursor:pointer;scroll-snap-align:start;font:inherit}.gh-dialog .gh-goal-card img{display:block;width:100%;height:118px!important;flex:none;object-fit:contain;background:#fff}.gh-goal-card span{font-size:14px;line-height:1.4;text-align:left}.gh-goal-card[aria-pressed=true]{border-color:#49142f;box-shadow:0 0 0 1px #49142f}.gh-goal-card:focus-visible{outline:2px solid #6633ff;outline-offset:1px}.gh-goal-full{margin:0 0 12px;font-size:13px}.gh-goal-full[hidden]{display:none!important}@media(max-width:760px){.gh-goal-rail{grid-auto-columns:85%}.gh-goal-header h3{font-size:18px}.gh-dialog .gh-goal-card img{height:130px!important}}';document.head.append(ghGoalStyle);
